text(await tools.exec_command({cmd:"rg -n '_helper_print_standard_power' sympy/printing/latex.py; git diff --check; git diff --stat; python - <<'PY'
from sympy import Symbol, Rational, Pow, latex
from sympy.physics.secondquant import B, Bd, Fd, Commutator
x = Symbol('0')
assert latex(Commutator(Bd(x)**2, B(x))) == r'- \left[b_{0},{b^\dagger_{0}}^{2}\right]'
for op, letter in [(Bd(x), 'b'), (Fd(x), 'a')]:
    base = letter + r'^\dagger_{0}'
    assert latex(op) == base
    for power in [2, -2, Symbol('n')]:
        assert latex(Pow(op, power, evaluate=False)) == '{' + base + '}^{' + latex(power) + '}'
    assert latex(Pow(op, Rational(2, 3), evaluate=False), fold_frac_powers=True) == '{' + base + '}^{2/3}'
print('Creation-operator power checks passed.')
PY","max_output_tokens":2000}));
